-- Nexus initial schema. Run with Supabase SQL editor or `supabase db push`.
create extension if not exists pgcrypto;
create type public.app_role as enum ('user','moderator','admin');
create schema if not exists private;
revoke all on schema private from public, anon;
grant usage on schema private to authenticated;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text unique,display_name text not null default 'Nexus üyesi',bio text not null default '',avatar_url text,website text,role public.app_role not null default 'user',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index profiles_username_lower_unique on public.profiles (lower(username)) where username is not null;
create table public.posts(id uuid primary key default gen_random_uuid(),author_id uuid not null references public.profiles(id) on delete cascade,body text not null check(length(body)<=5000),media_path text,kind text not null default 'post',visibility text not null default 'public' check(visibility in ('public','followers','private')),created_at timestamptz not null default now());
create table public.comments(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts(id) on delete cascade,author_id uuid not null references public.profiles(id) on delete cascade,parent_id uuid references public.comments(id) on delete cascade,body text not null check(length(body)<=3000),created_at timestamptz not null default now());
create table public.post_likes(post_id uuid references public.posts(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(post_id,user_id));
create table public.saved_posts(post_id uuid references public.posts(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(post_id,user_id));
create table public.follows(follower_id uuid references public.profiles(id) on delete cascade,following_id uuid references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(follower_id,following_id),check(follower_id<>following_id));
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,actor_id uuid references public.profiles(id) on delete set null,kind text not null,entity_id uuid,message text,read_at timestamptz,created_at timestamptz not null default now());
create table public.conversations(id uuid primary key default gen_random_uuid(),created_by uuid not null references public.profiles(id),title text,updated_at timestamptz not null default now(),created_at timestamptz not null default now());
create table public.conversation_members(conversation_id uuid references public.conversations(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,joined_at timestamptz not null default now(),primary key(conversation_id,user_id));
create table public.messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,sender_id uuid not null references public.profiles(id) on delete cascade,body text not null check(length(body)<=10000),created_at timestamptz not null default now());
create table public.debates(id uuid primary key default gen_random_uuid(),author_id uuid not null references public.profiles(id),title text not null,description text not null,category text not null default 'Genel',source_url text,visibility text not null default 'public',created_at timestamptz not null default now());
create table public.debate_votes(debate_id uuid references public.debates(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,vote text not null check(vote in ('agree','disagree')),primary key(debate_id,user_id));
create table public.courses(id uuid primary key default gen_random_uuid(),author_id uuid not null references public.profiles(id),title text not null,description text not null,level text,resource_url text,visibility text not null default 'public',created_at timestamptz not null default now());
create table public.course_lessons(id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses(id) on delete cascade,title text not null,content text,video_url text,file_path text,position int not null default 0);
create table public.course_enrollments(course_id uuid references public.courses(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(course_id,user_id));
create table public.course_reviews(id uuid primary key default gen_random_uuid(),course_id uuid references public.courses(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,rating int not null check(rating between 1 and 5),body text,created_at timestamptz not null default now(),unique(course_id,user_id));
create table public.ideas(id uuid primary key default gen_random_uuid(),author_id uuid not null references public.profiles(id),title text not null,description text not null,stage text not null default 'early',category text not null default 'Genel',visibility text not null default 'public',created_at timestamptz not null default now());
create table public.idea_votes(idea_id uuid references public.ideas(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(idea_id,user_id));
create table public.projects(id uuid primary key default gen_random_uuid(),author_id uuid not null references public.profiles(id),title text not null,description text not null,technologies text[] not null default '{}',github_url text,demo_url text,looking_for_team boolean not null default false,visibility text not null default 'public',created_at timestamptz not null default now());
create table public.project_stars(project_id uuid references public.projects(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(project_id,user_id));
create table public.communities(id uuid primary key default gen_random_uuid(),created_by uuid not null references public.profiles(id),name text not null,slug text not null unique,description text not null default '',is_private boolean not null default false,created_at timestamptz not null default now());
create table public.community_members(community_id uuid references public.communities(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,role text not null default 'member',joined_at timestamptz not null default now(),primary key(community_id,user_id));
create table public.reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references public.profiles(id),target_type text not null,target_id uuid not null,reason text not null,status text not null default 'open',reviewed_by uuid references public.profiles(id),created_at timestamptz not null default now());
create or replace function private.current_app_role() returns public.app_role language sql stable security definer set search_path=pg_catalog,public,auth as $$ select coalesce((select (raw_app_meta_data->>'role')::public.app_role from auth.users where id=(select auth.uid())),'user'::public.app_role) $$;
create or replace function private.is_admin() returns boolean language sql stable security definer set search_path=pg_catalog,public,auth as $$ select private.current_app_role()='admin' $$;
create or replace function private.is_conversation_member(conversation uuid) returns boolean language sql stable security definer set search_path=pg_catalog,public,auth as $$ select exists(select 1 from public.conversation_members where conversation_id=conversation and user_id=(select auth.uid())) $$;
create or replace function private.is_community_member(community uuid) returns boolean language sql stable security definer set search_path=pg_catalog,public,auth as $$ select exists(select 1 from public.community_members where community_id=community and user_id=(select auth.uid())) $$;
revoke all on all functions in schema private from public, anon;
grant execute on function private.current_app_role() to authenticated;
grant execute on function private.is_admin() to authenticated;
grant execute on function private.is_conversation_member(uuid) to authenticated;
grant execute on function private.is_community_member(uuid) to authenticated;
create index comments_parent_idx on public.comments(parent_id);create index communities_created_by_idx on public.communities(created_by);create index conversations_created_by_idx on public.conversations(created_by);create index course_enrollments_user_idx on public.course_enrollments(user_id);create index course_lessons_course_idx on public.course_lessons(course_id);create index course_reviews_user_idx on public.course_reviews(user_id);create index courses_author_idx on public.courses(author_id);create index debate_votes_user_idx on public.debate_votes(user_id);create index idea_votes_user_idx on public.idea_votes(user_id);create index ideas_author_idx on public.ideas(author_id);create index messages_sender_idx on public.messages(sender_id);create index notifications_actor_idx on public.notifications(actor_id);create index post_likes_user_idx on public.post_likes(user_id);create index project_stars_user_idx on public.project_stars(user_id);create index projects_author_idx on public.projects(author_id);create index reports_reporter_idx on public.reports(reporter_id);create index reports_reviewed_by_idx on public.reports(reviewed_by);create index saved_posts_user_idx on public.saved_posts(user_id);create index posts_feed_idx on public.posts(visibility,created_at desc);create index posts_author_idx on public.posts(author_id,created_at desc);create index comments_post_idx on public.comments(post_id,created_at);create index comments_author_idx on public.comments(author_id,created_at desc);create index notifications_user_idx on public.notifications(user_id,created_at desc);create index messages_conversation_idx on public.messages(conversation_id,created_at);create index conversation_members_user_idx on public.conversation_members(user_id,conversation_id);create index follows_following_idx on public.follows(following_id,follower_id);create index debates_feed_idx on public.debates(visibility,created_at desc);create index debates_author_idx on public.debates(author_id,created_at desc);create index courses_feed_idx on public.courses(visibility,created_at desc);create index ideas_feed_idx on public.ideas(visibility,created_at desc);create index projects_feed_idx on public.projects(visibility,created_at desc);create index community_members_user_idx on public.community_members(user_id,community_id);create index reports_status_created_idx on public.reports(status,created_at desc);
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$ declare requested_username text; chosen_username text; chosen_display_name text; begin requested_username:=lower(btrim(coalesce(new.raw_user_meta_data->>'username',''))); chosen_display_name:=coalesce(nullif(btrim(new.raw_user_meta_data->>'display_name'),''),nullif(btrim(new.raw_user_meta_data->>'full_name'),''),nullif(requested_username,''),'Nexus üyesi'); if requested_username ~ '^[a-z0-9_-]{3,24}$' then chosen_username:=requested_username; else chosen_username:='user-'||substr(new.id::text,1,8); end if; insert into public.profiles(id,username,display_name) values(new.id,chosen_username,chosen_display_name) on conflict(id) do update set username=excluded.username,display_name=excluded.display_name; return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create function public.add_conversation_creator() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.conversation_members(conversation_id,user_id) values(new.id,new.created_by) on conflict do nothing; return new; end; $$;
create trigger conversation_creator after insert on public.conversations for each row execute procedure public.add_conversation_creator();
create function public.add_community_creator() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.community_members(community_id,user_id,role) values(new.id,new.created_by,'owner') on conflict do nothing; return new; end; $$;
create trigger community_creator after insert on public.communities for each row execute procedure public.add_community_creator();
revoke all on function public.handle_new_user() from public, anon, authenticated;
revoke all on function public.add_conversation_creator() from public, anon, authenticated;
revoke all on function public.add_community_creator() from public, anon, authenticated;
do $$ declare t text; begin foreach t in array array['profiles','posts','comments','post_likes','saved_posts','follows','notifications','conversations','conversation_members','messages','debates','debate_votes','courses','course_lessons','course_enrollments','course_reviews','ideas','idea_votes','projects','project_stars','communities','community_members','reports'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy "profiles are publicly readable" on public.profiles for select using(true);create policy "profile owners update profile" on public.profiles for update using(id=(select auth.uid()) or private.is_admin()) with check(id=(select auth.uid()) or private.is_admin());create policy "new users create own profile" on public.profiles for insert with check(id=(select auth.uid()));
create policy "public posts readable" on public.posts for select using(visibility='public' or author_id=(select auth.uid()) or private.is_admin());create policy "authors create posts" on public.posts for insert with check(author_id=(select auth.uid()));create policy "authors update posts" on public.posts for update using(author_id=(select auth.uid()) or private.is_admin()) with check(author_id=(select auth.uid()) or private.is_admin());create policy "authors or admins delete posts" on public.posts for delete using(author_id=(select auth.uid()) or private.is_admin());
create policy "comments readable with post" on public.comments for select using(exists(select 1 from public.posts p where p.id=post_id and (p.visibility='public' or p.author_id=(select auth.uid()))));create policy "authenticated create comments" on public.comments for insert with check(author_id=(select auth.uid()));create policy "comment owners delete" on public.comments for delete using(author_id=(select auth.uid()) or private.is_admin());
create policy "likes visible" on public.post_likes for select using(true);create policy "own likes" on public.post_likes for insert with check(user_id=(select auth.uid()));create policy "remove own likes" on public.post_likes for delete using(user_id=(select auth.uid()));
create policy "own saved posts" on public.saved_posts for all using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));create policy "follows visible" on public.follows for select using(true);create policy "follow as self" on public.follows for insert with check(follower_id=(select auth.uid()));create policy "unfollow self" on public.follows for delete using(follower_id=(select auth.uid()));
create policy "own notifications" on public.notifications for select using(user_id=(select auth.uid()));create policy "mark own notifications" on public.notifications for update using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy "own conversations visible" on public.conversations for select using(private.is_conversation_member(id));create policy "authenticated create conversation" on public.conversations for insert with check(created_by=(select auth.uid()));create policy "members visible" on public.conversation_members for select using(private.is_conversation_member(conversation_id));create policy "creator adds members" on public.conversation_members for insert with check(exists(select 1 from public.conversations c where c.id=conversation_id and c.created_by=(select auth.uid())));create policy "members read messages" on public.messages for select using(private.is_conversation_member(conversation_id));create policy "members send own messages" on public.messages for insert with check(sender_id=(select auth.uid()) and private.is_conversation_member(conversation_id));
do $$ declare t text; begin foreach t in array array['debates','courses','ideas','projects'] loop execute format('create policy "public read %1$s" on public.%1$I for select using(visibility=''public'' or author_id=(select auth.uid()) or private.is_admin())',t); execute format('create policy "author create %1$s" on public.%1$I for insert with check(author_id=(select auth.uid()))',t); execute format('create policy "author modify %1$s" on public.%1$I for update using(author_id=(select auth.uid()) or private.is_admin()) with check(author_id=(select auth.uid()) or private.is_admin())',t); execute format('create policy "author delete %1$s" on public.%1$I for delete using(author_id=(select auth.uid()) or private.is_admin())',t); end loop; end $$;
create policy "debate votes visible" on public.debate_votes for select using(true);create policy "insert own debate vote" on public.debate_votes for insert to authenticated with check(user_id=(select auth.uid()));create policy "update own debate vote" on public.debate_votes for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));create policy "delete own debate vote" on public.debate_votes for delete to authenticated using(user_id=(select auth.uid()));create policy "read public or owned course lessons" on public.course_lessons for select using(exists(select 1 from public.courses c where c.id=course_id and (c.visibility='public' or c.author_id=(select auth.uid()))));create policy "course authors add lessons" on public.course_lessons for insert to authenticated with check(exists(select 1 from public.courses c where c.id=course_id and c.author_id=(select auth.uid())));create policy "course authors update lessons" on public.course_lessons for update to authenticated using(exists(select 1 from public.courses c where c.id=course_id and c.author_id=(select auth.uid()))) with check(exists(select 1 from public.courses c where c.id=course_id and c.author_id=(select auth.uid())));create policy "course authors delete lessons" on public.course_lessons for delete to authenticated using(exists(select 1 from public.courses c where c.id=course_id and c.author_id=(select auth.uid())));create policy "own enrollments" on public.course_enrollments for all using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));create policy "reviews public" on public.course_reviews for select using(true);create policy "own review" on public.course_reviews for insert with check(user_id=(select auth.uid()));create policy "own review update" on public.course_reviews for update using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));create policy "idea votes public" on public.idea_votes for select using(true);create policy "insert own idea vote" on public.idea_votes for insert to authenticated with check(user_id=(select auth.uid()));create policy "update own idea vote" on public.idea_votes for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));create policy "delete own idea vote" on public.idea_votes for delete to authenticated using(user_id=(select auth.uid()));create policy "project stars public" on public.project_stars for select using(true);create policy "insert own project star" on public.project_stars for insert to authenticated with check(user_id=(select auth.uid()));create policy "update own project star" on public.project_stars for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));create policy "delete own project star" on public.project_stars for delete to authenticated using(user_id=(select auth.uid()));
create policy "public communities readable" on public.communities for select using(not is_private or private.is_community_member(id));create policy "authenticated create community" on public.communities for insert with check(created_by=(select auth.uid()));create policy "owner manage community" on public.communities for update using(created_by=(select auth.uid()) or private.is_admin()) with check(created_by=(select auth.uid()) or private.is_admin());create policy "community members visible" on public.community_members for select using(private.is_community_member(community_id));create policy "join public community" on public.community_members for insert with check(user_id=(select auth.uid()) and exists(select 1 from public.communities c where c.id=community_id and not c.is_private));create policy "leave community" on public.community_members for delete using(user_id=(select auth.uid()) or private.is_admin());
create policy "reporters create reports" on public.reports for insert with check(reporter_id=(select auth.uid()));create policy "reporter or admins view reports" on public.reports for select using(reporter_id=(select auth.uid()) or private.is_admin());create policy "admins manage reports" on public.reports for update using(private.is_admin()) with check(private.is_admin());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('nexus-media','nexus-media',false,52428800,array['image/jpeg','image/png','image/webp','image/gif','video/mp4','application/pdf']) on conflict(id) do nothing;
create policy "authenticated upload own media" on storage.objects for insert to authenticated with check(bucket_id='nexus-media' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy "owner reads own media" on storage.objects for select to authenticated using(bucket_id='nexus-media' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy "public post media read" on storage.objects for select using(bucket_id='nexus-media' and exists(select 1 from public.posts p where p.media_path=name and p.visibility='public'));
create policy "owner deletes own media" on storage.objects for delete to authenticated using(bucket_id='nexus-media' and (storage.foldername(name))[1]=(select auth.uid())::text);


-- Keep authorization metadata out of client-controlled profile updates.
revoke update on table public.profiles from anon, authenticated;
grant update (display_name, bio, avatar_url, website, updated_at)
  on table public.profiles to authenticated;
